from lib import *
S = SS('j260')
steps = [
    step("两个 JVM 进程之间(JDK 21,macOS):A 持有整个文件的独占锁 2 秒。B 的 tryLock 立即返回 null(14 ms);B 的阻塞 lock() 等了 1934 ms,在 A 释放后拿到锁(A 在 2028 ms 释放)。A 持有共享锁时:B 申请共享拿到了,B 申请独占得到 null。区域锁:A 独占 [0, 100) 时 B 申请 [100, 200) 拿到了,申请 [50, 150)(重叠)得到 null。", t=tl(S(1)), done=lidx(S(1), 'B tryLock(独占,整个文件)', 'B lock()(阻塞)'), mark=lidx(S(1), 'A 持有共享锁时 B 申请共享', 'A 持有共享锁时 B 申请独占', '[100, 200)', '[50, 150)'), kv=KV([['A 独占时 B tryLock / lock()', 'null / 阻塞 1934 ms 后拿到'], ['A 共享时 B 共享 / 独占', '拿到 / null'], ['A 独占 [0, 100)', 'B [100, 200) 拿到,B [50, 150) null']], ['A 独占 [0, 100)'])),
    step("同一个 JVM 内的规则不同:通道 c1 独占锁 [0, 100) 之后,通道 c2 申请 [0, 100)(独占或共享)或 [50, 150),抛的是 OverlappingFileLockException(不是返回 null);申请不重叠的 [100, 200) 才拿到。c1 的锁 isValid = true、isShared = false,释放后 isValid = false。同一个 JVM 里重叠区域根本不会走到操作系统,由 JVM 自己拒绝。", t=tl(S(2)), done=lidx(S(2), 'c1 独占 [0, 100)', 'c2 独占 [0, 100):OverlappingFileLockException'), mark=lidx(S(2), '[50, 150)', '[100, 200)', 'c2 共享', 'isValid'), kv=KV([['同 JVM 重叠', 'OverlappingFileLockException(不是 null)'], ['同 JVM 不重叠 [100, 200)', '拿到']], ['同 JVM 重叠'])),
    step("锁是建议性的:A 持有整个文件的独占锁,B 完全不申请锁、直接用 FileOutputStream 追加写——写成功了(“WROTE(没有申请锁),文件现在 15 字节”),文件最终内容是 B 写的“无视锁写入”。FileChannel.lock 只对同样去申请锁的程序有约束,不会阻止别的写入。", t=tl(S(3)), done=lidx(S(3), 'B 直接写'), mark=lidx(S(3), '文件最终内容'), kv=KV([['A 持有独占锁', '整个文件'], ['B 不申请锁直接写', '写成功,文件被改']], ['B 不申请锁直接写'])),
    step("锁什么时候被释放:A 持有时 B tryLock 返回 null;kill -9 A 之后 B 立即(间隔 0.00 s)tryLock 成功——操作系统在进程死亡时释放了锁,不需要清理。但另一个陷阱:A 在同一个进程里持有 c1 的独占锁,再打开同一个文件的另一个通道 c2 并关闭它,A 的 FileLock.isValid 仍然是 true(JDK 自己的状态),A 还在 HOLDING 时 B 的 tryLock 却成功了——在这个平台上,关闭同一进程里同一个文件的任何通道,都会丢掉这个进程在该文件上的锁(这是 POSIX fcntl 锁的语义;只在 macOS 上验证了)。", t=tl(S(4)), done=lidx(S(4), 'A 持有时 B tryLock', 'kill -9 A 之后'), mark=lidx(S(4), '关闭同一个文件的另一个通道 c2 之后', 'A 还在 HOLDING 时 B tryLock'), kv=KV([['kill -9 A', 'B 立即拿到锁'], ['在 A 里关闭同文件的另一个通道', 'A 的 isValid 仍是 true,B 却拿到了锁']], ['在 A 里关闭同文件的另一个通道'])),
    step("用锁文件(app.lock)互斥时的陷阱:A 持有 app.lock 的独占锁,锁文件被删除(Files.delete,326 ms);B 对同一个路径 tryLock 成功——它创建了一个新文件,锁的是另一个 inode;A 的锁 isValid 仍是 true(1836 ms)。两个进程都以为自己拿着独占锁。锁属于被打开的文件,不属于路径;锁文件不能被删除。", t=tl(S(5)), done=lidx(S(5), 'LOCKED 独占 app.lock', 'DELETED'), mark=lidx(S(5), 'B 在 A 删除锁文件之后', 'A 的锁 isValid = true'), kv=KV([['A', '持有 app.lock,文件被删除后锁仍 isValid = true'], ['B', '对同一路径 tryLock 成功(新文件)']], ['B'])),
]
A = mkartj('j260', 260, 'Java,NIO,FileChannel,文件锁,FileLock,跨进程,真实验证,动画演示',
    '在 JDK 21 / macOS 上用两个 JVM 实测 FileChannel.lock:tryLock 返回 null、lock() 阻塞 1934 ms、共享与区域锁的规则;同一 JVM 内重叠抛 OverlappingFileLockException;锁只是建议性的(B 不申请锁照样写入);kill -9 后立即释放,但关闭同进程内同文件的另一个通道会丢锁(isValid 仍为 true);锁文件被删除后两个进程都拿到锁。',
    '“用文件锁做跨进程互斥”看上去很简单。这篇用两个真实的 JVM 进程量出它的规则和边界:阻塞与非阻塞、共享与区域、同 JVM 与跨进程的差别,以及几个会让两个进程同时进入临界区的陷阱。',
    [('1934 ms', 'A 持有独占锁 2 秒时,B 的 lock() 等待的时间(tryLock 立即返回 null)'), ('isValid = true,但锁已丢', '同一进程里关闭同一个文件的另一个通道之后,另一个进程的 tryLock 成功了(macOS)'), ('2 个持有者', '锁文件被删除再重建后,A 与 B 都以为自己持有独占锁')],
    [('跨进程互斥', None), ('同一个 JVM 内', None), ('建议性', None), ('释放的时机与陷阱', None), ('锁文件被删除', None)],
    steps, [ENV_J + '。JDK 21.0.12,macOS arm64(本地 APFS 文件系统);进程由 Python 启动并用 stdout 同步', '没有验证:Linux(同样是 fcntl,但 NFS 上不同)、Windows(强制锁定,语义与建议性相反)、网络文件系统(NFS / SMB)上的行为、flock 与 fcntl 的差别(JDK 只用 fcntl)、容器里 bind mount 的文件锁、关闭另一个通道丢锁这一点在 Linux 上的行为'], 'FileChannel.lock')
